{"code": "
const fs = await import('fs');
const codes = ['cx-08','cx-09','cx-10','cx-11','cx-12','cx-13','cx-14'];
const expected = {
  'cx-08':['CX-08','codex','Codex-Subagents多Agent协作'],
  'cx-09':['CX-09','codex','Codex-Automations后台任务'],
  'cx-10':['CX-10','codex','Codex-Review-GitHub-PR'],
  'cx-11':['CX-11','codex','Codex-Web-Cloud辅助'],
  'cx-12':['CX-12','codex','Codex-CLI辅助'],
  'cx-13':['CX-13','codex','Codex安全企业'],
  'cx-14':['CX-14','codex','Codex与Claude-Code对比'],
};
const report = [];
for (const c of codes) {
  const p = `vibe-coding-ppt/tutorials-content/${c}.json`;
  let d;
  try { d = JSON.parse(fs.readFileSync(p,'utf8')); } catch(e){ report.push(`${c}: JSON PARSE FAIL ${e.message}`); continue; }
  const errs = [];
  if (d.code !== expected[c][0]) errs.push('code mismatch');
  if (d.category !== expected[c][1]) errs.push('category mismatch');
  if (d.fileTitle !== expected[c][2]) errs.push('fileTitle mismatch '+d.fileTitle);
  const n = d.slides.length;
  if (n < 10 || n > 14) errs.push(`slides=${n}`);
  const layouts = {};
  d.slides.forEach((s, i) => {
    layouts[s.layout] = (layouts[s.layout]||0)+1;
    if (s.layout === 'cover') {
      if (s.kicker !== `Vibe Coding 学习系列 · ${d.code}`) errs.push(`slide${i+1} kicker=${s.kicker}`);
    }
    if (s.layout === 'bullets') {
      if (!Array.isArray(s.bullets) || s.bullets.length < 1 || s.bullets.length > 5) errs.push(`slide${i+1} bullets count=${s.bullets && s.bullets.length}`);
      (s.bullets||[]).forEach((b,j)=>{ if (b.length > 42) errs.push(`slide${i+1} bullet${j+1} len=${b.length}: ${b}`); });
    }
    if (s.layout === 'cards') {
      if (!Array.isArray(s.cards) || s.cards.length < 3 || s.cards.length > 4) errs.push(`slide${i+1} cards count=${s.cards && s.cards.length}`);
    }
    if (s.layout === 'steps') {
      if (!Array.isArray(s.steps) || s.steps.length < 3 || s.steps.length > 4) errs.push(`slide${i+1} steps count=${s.steps && s.steps.length}`);
    }
    if (s.layout === 'table') {
      if (s.headers.length > 5) errs.push(`slide${i+1} headers=${s.headers.length}`);
      if (s.rows.length > 6) errs.push(`slide${i+1} rows=${s.rows.length}`);
      s.rows.forEach((r,j)=>{ if (r.length !== s.headers.length) errs.push(`slide${i+1} row${j+1} width=${r.length} vs ${s.headers.length}`); });
    }
  });
  report.push(`${c}: slides=${n} ${JSON.stringify(layouts)} ${errs.length? 'ERRORS: '+errs.join(' | ') : 'OK'}`);
}
console.log(report.join('\n'));
", "description": "Validate all seven deck JSON files"}

