  const d = JSON.parse(fs.readFileSync(`vibe-coding-ppt/tutorials-content/${c}.json`,'utf8'));
  const errs = [];
  const n = d.slides.length;
  d.slides.forEach((s,i)=>{
    if (s.layout==='cover' && s.kicker !== `Vibe Coding 学习系列 · ${d.code}`) errs.push(`kicker s${i+1}`);
    if (s.layout==='bullets') (s.bullets||[]).forEach((b,j)=>{ if(b.length>42) errs.push(`bullet s${i+1}.${j+1} len=${b.length}`); if((s.bullets||[]).length>5) errs.push('count'); });
    if (s.layout==='cards' && (s.cards.length<3||s.cards.length>4)) errs.push('cards');
    if (s.layout==='steps' && (s.steps.length<3||s.steps.length>4)) errs.push('steps');
    if (s.layout==='table'){ if(s.headers.length>5||s.rows.length>6) errs.push('table'); }
  });
  out.push(`${d.code} | ${d.deck} | slides=${n} | ${errs.length? 'ERR '+errs.join(','):'OK'}`);
}
